    static Matrix4x4 Pose(Spline.TransformTrack t,float frame){Vector3 p=t.StaticPosition,s=t.StaticScale;if(t.HasSplinePosition)p=new(t.SplinePosition.GetValueX(frame)??p.X,t.SplinePosition.GetValueY(frame)??p.Y,t.SplinePosition.GetValueZ(frame)??p.Z);if(t.HasSplineScale)s=new(t.SplineScale.GetValueX(frame)??s.X,t.SplineScale.GetValueY(frame)??s.Y,t.SplineScale.GetValueZ(frame)??s.Z);return Matrix4x4.CreateScale(s)*Matrix4x4.CreateFromQuaternion(Quaternion.Normalize(t.HasSplineRotation?t.SplineRotation.GetValue(frame):t.StaticRotation))*Matrix4x4.CreateTranslation(p);}
    static Vector3[] Bounds(FLVER2 model,byte[] rigBytes,byte[] clipBytes,float fraction) {
        var rig=NativeAnimation.Skeleton(rigBytes,true);var pack=new NativeAnimation.Pack(clipBytes);int at=pack.Object("hkaSplineCompressedAnimation");var data=pack.Array(at+152,1,64*1024*1024);var block=Spline.ReadSplineCompressedAnimByteBlock(false,clipBytes.AsSpan(pack.Data+data.At,data.Count).ToArray(),rig.Names.Length,pack.Int(at+60));float frame=(pack.Int(at+56)-1)*fraction;int which=(int)frame/255;var current=new Matrix4x4[rig.Names.Length];for(int i=0;i<current.Length;i++)current[i]=Pose(block[which][i],frame-which*255)*(rig.Parents[i]<0?Matrix4x4.Identity:current[rig.Parents[i]]);
