        var low=new Vector3(float.MaxValue);var high=new Vector3(float.MinValue);foreach(var mesh in model.Meshes)foreach(var v in mesh.Vertices){var p=Vector3.Zero;for(int i=0;i<4;i++)if(v.BoneWeights[i]>0)p+=Vector3.Transform(v.Position,skin[SkinRetarget.Bone(mesh,v.BoneIndices[i])])*v.BoneWeights[i];Need(float.IsFinite(p.X)&&float.IsFinite(p.Y)&&float.IsFinite(p.Z),"Pose vertex nonfinite");low=Vector3.Min(low,p);high=Vector3.Max(high,p);}return[low,high];
