    static float? Floor(MapCollision.Triangle t,float x,float z) {
        float cross=(t.B.X-t.A.X)*(t.C.Z-t.A.Z)-(t.C.X-t.A.X)*(t.B.Z-t.A.Z);if(Math.Abs(cross)<.00001f)return null;
