    static bool Hit(Vector3 from,Vector3 to,MapCollision.Triangle t) {
        var d=to-from;var e1=t.B-t.A;var e2=t.C-t.A;var p=Vector3.Cross(d,e2);float det=Vector3.Dot(e1,p);if(Math.Abs(det)<.000001f)return false;var q=from-t.A;float u=Vector3.Dot(q,p)/det;if(u<0||u>1)return false;var r=Vector3.Cross(q,e1);float v=Vector3.Dot(d,r)/det;if(v<0||u+v>1)return false;float distance=Vector3.Dot(e2,r)/det;return distance>.001f&&distance<.999f;
    }
    static void Main(string[] args){string source=args[0],candidate=args[1],defs=Path.Combine(args[2],"src/Smithbox.Data/Assets/PARAM/DS1R/Defs"),output="out/map-editor/catacombs-visibility";Directory.CreateDirectory(output);byte[]? Source(string p)=>File.Exists(Path.Combine(source,p))?File.ReadAllBytes(Path.Combine(source,p)):null;byte[] Export(string p)=>File.ReadAllBytes(Path.Combine(candidate,"dvdroot_ps4",p));
