        var map=MSB1.Read(Source("map/MapStudio/m13_00_00_00.msb")!);var plan=CatacombsCreaturesSource.Load(Source,map,defs);using var manifest=JsonDocument.Parse(File.ReadAllBytes(Path.Combine(candidate,"maps/m13_00_00_00/conversion.json")));var origin=manifest.RootElement.GetProperty("offset");var offset=new Vector3(origin.GetProperty("X").GetSingle(),origin.GetProperty("Y").GetSingle(),origin.GetProperty("Z").GetSingle());string targetMap=manifest.RootElement.GetProperty("target").GetString()!;var native=MSBB.Read(Export("map/MapStudio/"+targetMap+".msb.dcx"));var npcs=BND4.Read(Export("param/gameparam/gameparam.parambnd.dcx"));var npc=PARAM.Read(npcs.Files.Single(f=>Leaf(f.Name)=="NpcParam.param").Bytes);npc.ApplyParamdef(PARAMDEF.XmlDeserialize(Path.GetFullPath(Path.Combine(defs,"../../BB/Defs/NpcParam.xml"))));
