        foreach(var s in sourceActors){int entity=s.EntityID switch{1300201=>4058024,1300203=>4058025,1300180=>4058054,1300200=>4058055,_=>throw new Exception()};var actor=native.Parts.Enemies.Single(p=>p.EntityID==entity);var row=npc.Rows.Single(r=>r.ID==actor.NPCParamID);var cb=BND4.Read(Export("chr/"+actor.ModelName+".chrbnd.dcx"));var ab=BND4.Read(Export("chr/"+actor.ModelName+".anibnd.dcx"));var model=FLVER2.Read(cb.Files.Single(f=>Leaf(f.Name).EndsWith(".flver",StringComparison.OrdinalIgnoreCase)).Bytes);var clip=ab.Files.Single(f=>f.ID==1000000000).Bytes.ToArray();var rig=ab.Files.Single(f=>f.ID==1000000).Bytes.ToArray();var posed=Bounds(model,rig,clip,.5f);var cohort=plan.Cohorts.SingleOrDefault(c=>c.Caster.EntityID==s.EntityID||c.Skeletons.Any(a=>a.EntityID==s.EntityID));
            records.Add(new{entity,Source=s.Name,s.EntityID,s.InitAnimID,s.CollisionName,SourcePosition=V(s.Position),TargetPosition=V(actor.Position),SourceRotation=V(s.Rotation),TargetRotation=V(actor.Rotation),Scale=V(actor.Scale),actor.DrawGroups,actor.DispGroups,actor.BackreadGroups,NativeMasks=Enumerable.Range(0,32).Where(i=>Convert.ToInt32(row["modelDispMask"+i].Value)>0).ToArray(),Wake=plan.Wakes.SingleOrDefault(w=>w.Entity==s.EntityID),Caster=cohort?.Caster.EntityID,Meshes=model.Meshes.Select(m=>new{m.MaterialIndex,Vertices=m.Vertices.Count,Triangles=m.FaceSets.Sum(f=>f.Indices.Count/3),Min=V(m.BoundingBox!.Min),Max=V(m.BoundingBox.Max)}),Materials=model.Materials.Select(m=>new{m.Name,m.Index,m.MTD}),HeaderMin=V(model.Header.BoundingBoxMin),HeaderMax=V(model.Header.BoundingBoxMax),IdleMidMin=V(posed[0]),IdleMidMax=V(posed[1])});
        }
        var target=sourceActors.Single(a=>a.EntityID==1300201).Position+offset;var candidates=new List<object>();foreach(float radius in new[]{2f,3f,4f,5f})for(int degrees=0;degrees<360;degrees+=15){float angle=degrees*MathF.PI/180;float x=target.X+MathF.Sin(angle)*radius,z=target.Z+MathF.Cos(angle)*radius;var heights=solid.Select(t=>Floor(t,x,z)).Where(y=>y.HasValue&&Math.Abs(y.Value-target.Y)<1.25f).Select(y=>y!.Value).OrderBy(y=>Math.Abs(y-target.Y)).ToArray();if(heights.Length==0)continue;var point=new Vector3(x,heights[0]+.08f,z);bool clear= !solid.Any(t=>Hit(point+new Vector3(0,1.5f,0),target+new Vector3(0,1.2f,0),t));if(!clear)continue;bool ringClear=true;foreach(var delta in new[]{new Vector3(.35f,.5f,0),new Vector3(-.35f,.5f,0),new Vector3(0,.5f,.35f),new Vector3(0,.5f,-.35f)})if(solid.Any(t=>Hit(point+new Vector3(0,.5f,0),point+delta,t)))ringClear=false;if(ringClear)candidates.Add(new{Position=V(point),Heading=MathF.Atan2(target.X-point.X,target.Z-point.Z),Distance=radius,LineOfSight=true});}
