        var placed=manifest.RootElement.GetProperty("placementResults").EnumerateArray().Where(p=>p.GetProperty("status").GetString()=="placed-static").Select(p=>p.GetProperty("targetName").GetString()!).ToHashSet();var visual=new List<(string Name,MapCollision.Triangle Face)>();var models=new Dictionary<string,FLVER2>();foreach(var part in native.Parts.MapPieces.Where(p=>placed.Contains(p.Name))) {if(!models.TryGetValue(part.ModelName,out var model)){model=FLVER2.Read(Export("map/"+targetMap+"/"+targetMap+"_"+part.ModelName[1..]+".flver.dcx"));models.Add(part.ModelName,model);}var rotation=part.Rotation*MathF.PI/180;var transform=Matrix4x4.CreateScale(part.Scale)*Matrix4x4.CreateRotationX(rotation.X)*Matrix4x4.CreateRotationZ(rotation.Z)*Matrix4x4.CreateRotationY(rotation.Y)*Matrix4x4.CreateTranslation(part.Position);var lo=new Vector3(float.MaxValue);var hi=new Vector3(float.MinValue);foreach(float x in new[]{model.Header.BoundingBoxMin.X,model.Header.BoundingBoxMax.X})foreach(float y in new[]{model.Header.BoundingBoxMin.Y,model.Header.BoundingBoxMax.Y})foreach(float z in new[]{model.Header.BoundingBoxMin.Z,model.Header.BoundingBoxMax.Z}){var p=Vector3.Transform(new(x,y,z),transform);lo=Vector3.Min(lo,p);hi=Vector3.Max(hi,p);}if(hi.X<target.X-8||lo.X>target.X+8||hi.Z<target.Z-8||lo.Z>target.Z+8||hi.Y<target.Y-3||lo.Y>target.Y+5)continue;
            foreach(var mesh in model.Meshes){string mtd=model.Materials[mesh.MaterialIndex].MTD;if(mtd.Contains("_e.",StringComparison.OrdinalIgnoreCase)||mtd.Contains("_al.",StringComparison.OrdinalIgnoreCase))continue;foreach(var face in mesh.FaceSets.Where(f=>f.Flags==FLVER2.FaceSet.FSFlags.None)){var indices=face.Triangulate(mesh.Vertices.Count<65535);for(int i=0;i<indices.Count;i+=3){var a=Vector3.Transform(mesh.Vertices[indices[i]].Position,transform);var b=Vector3.Transform(mesh.Vertices[indices[i+1]].Position,transform);var c=Vector3.Transform(mesh.Vertices[indices[i+2]].Position,transform);if(new[]{a,b,c}.Any(p=>Vector2.Distance(new(p.X,p.Z),new(target.X,target.Z))<8&&Math.Abs(p.Y-target.Y)<5))visual.Add((part.Name,new(a,b,c)));}}}
