        var options=new JsonSerializerOptions{WriteIndented=true};File.WriteAllText(Path.Combine(output,"actors.json"),JsonSerializer.Serialize(records,options));File.WriteAllText(Path.Combine(output,"viewpoints.json"),JsonSerializer.Serialize(views,options));File.WriteAllText(Path.Combine(output,"visual-blockers.json"),JsonSerializer.Serialize(new{CurrentPlayer=V(current),CurrentBlockers=currentBlockers,VisualTriangles=visual.Count},options));var local=solid.Where(t=>new[]{t.A,t.B,t.C}.Any(p=>Vector2.Distance(new(p.X,p.Z),new(target.X,target.Z))<8&&Math.Abs(p.Y-target.Y)<5)).Select(t=>new[]{V(t.A),V(t.B),V(t.C)}).ToArray();File.WriteAllText(Path.Combine(output,"local-solid.json"),JsonSerializer.Serialize(local));Console.WriteLine("Read-only visibility audit: actors"+records.Count+", clear authored-floor candidates"+views.Count(v=>v.Blockers.Length==0)+", local collision triangles"+local.Length+", visual triangles"+visual.Count+", current visual blockers"+string.Join(",",currentBlockers));
    }
